import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Hermes 引擎与小龙虾","description":"从 React Native 的 Hermes 引擎聊到性能优化的\\"小龙虾定律\\"——为什么去掉最贵的那一环，收益最大。","frontmatter":{"title":"Hermes 引擎与小龙虾","date":"2026-05-18T00:00:00.000Z","tags":["JavaScript","微信小程序"],"category":"随笔","description":"从 React Native 的 Hermes 引擎聊到性能优化的\\"小龙虾定律\\"——为什么去掉最贵的那一环，收益最大。"},"headers":[],"relativePath":"articles/note/hermes-vs-xiaolongxia.md","filePath":"articles/note/hermes-vs-xiaolongxia.md","articleMeta":{"updated":"2026-05-18","words":297,"minutes":1}}`),a={name:`articles/note/hermes-vs-xiaolongxia.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>为什么标题里有个小龙虾？因为性能优化和吃小龙虾有个共同点：<strong>先剥壳最麻烦的那只，后面就顺了</strong>。</p><h2 id="hermes-是什么" tabindex="-1">Hermes 是什么 <a class="header-anchor" href="#hermes-是什么" aria-label="Permalink to “Hermes 是什么”">​</a></h2><p>Hermes 是 Meta 为 React Native 打造的 JavaScript 引擎，核心特点：</p><ul><li>字节码预编译，跳过运行时 JIT 编译</li><li>启动时间显著缩短</li><li>内存占用更低</li></ul><h2 id="启发-小龙虾定律" tabindex="-1">启发：&quot;小龙虾定律&quot; <a class="header-anchor" href="#启发-小龙虾定律" aria-label="Permalink to “启发：&quot;小龙虾定律&quot;”">​</a></h2><p>性能优化时，最大的误区是到处小修小补。正确的做法是：</p><ol><li><strong>测量</strong>：找到真正的瓶颈（往往是启动、首屏、包体积）</li><li><strong>摘除</strong>：把&quot;最贵的环节&quot;整个拿掉（如 Hermes 跳过 JIT）</li><li><strong>验证</strong>：用数据确认收益</li></ol><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><p>与其在细节里抠 5% 的优化，不如找到架构层面可以&quot;整个剥掉&quot;的那只小龙虾。</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};